package pcre2

import (
	"encoding/hex"
	"encoding/json"
	"fmt"
	"os"
	"slices"
	"strconv"
	"testing"
)

// The fixtures of testdata/matchfix hold the bytecode that libpcre2 10.44
// compiled for a set of patterns, and the return code, ovector and mark that
// libpcre2 gave for many subjects, options and start offsets. They let the
// matcher be checked without the Go compiler: the Code is rebuilt from the
// bytes and run. They are generated by the out-of-tree rig, see rig_export.go.

type fixHeader struct {
	StartBitmap                                                                              [32]uint8
	Blocksize                                                                                uint64
	Magic, CompileOptions, OverallOptions, ExtraOptions, Flags                               uint32
	LimitHeap, LimitMatch, LimitDepth, FirstCodeunit, LastCodeunit                           uint32
	Bsr, Newline, MaxLookbehind, Minlength, TopBracket, TopBackref, NameEntrySize, NameCount uint16
}

type fixCase struct {
	Subject string
	Off     uint64
	Opts    uint32
	RC      int
	Ovector []uint64
	Mark    string
}

type fixture struct {
	Pattern string
	COpts   uint32
	Header  fixHeader
	Code    string
	Cases   []fixCase
}

func (f *fixture) code(t testing.TB) *Code {
	b, err := hex.DecodeString(f.Code)
	if err != nil {
		t.Fatal(err)
	}
	h := f.Header
	return &Code{
		startBitmap: h.StartBitmap, blocksize: h.Blocksize, magicNumber: h.Magic,
		compileOptions: h.CompileOptions, overallOptions: h.OverallOptions, extraOptions: h.ExtraOptions,
		flags: h.Flags, limitHeap: h.LimitHeap, limitMatch: h.LimitMatch, limitDepth: h.LimitDepth,
		firstCodeunit: h.FirstCodeunit, lastCodeunit: h.LastCodeunit,
		bsrConvention: h.Bsr, newlineConvention: h.Newline, maxLookbehind: h.MaxLookbehind,
		minlength: h.Minlength, topBracket: h.TopBracket, topBackref: h.TopBackref,
		nameEntrySize: h.NameEntrySize, nameCount: h.NameCount, code: b,
	}
}

func loadFixtures(t testing.TB) []fixture {
	b, err := os.ReadFile("testdata/matchfix/fixtures.json")
	if err != nil {
		t.Fatal(err)
	}
	var fx []fixture
	if err := json.Unmarshal(b, &fx); err != nil {
		t.Fatal(err)
	}
	return fx
}

// fixtureContext is the match context the fixtures were generated with.
func fixtureContext() *MatchContext {
	mc := NewMatchContext()
	mc.SetMatchLimit(100000)
	mc.SetDepthLimit(100000)
	mc.SetHeapLimit(20000)
	return mc
}

func TestMatchFixtures(t *testing.T) {
	n, bad := 0, 0
	for _, f := range loadFixtures(t) {
		code := f.code(t)
		md := NewMatchData(code)
		mc := fixtureContext()
		for _, c := range f.Cases {
			subj, _ := hex.DecodeString(c.Subject)
			rc := Match(code, subj, c.Off, c.Opts, md, mc)
			n++
			ok := rc == c.RC
			if ok && len(c.Ovector) > 0 {
				ov := md.Ovector()
				ok = len(ov) >= len(c.Ovector) && slices.Equal(ov[:len(c.Ovector)], c.Ovector)
			}
			if ok && c.RC >= 0 {
				mk := ""
				if m := md.GetMark(); m != nil {
					mk = hex.EncodeToString(m)
				}
				ok = mk == c.Mark
			}
			if !ok {
				bad++
				if bad <= 20 {
					t.Errorf("/%s/ opts %#x subject %q off %d: rc %d ovector %v, want rc %d ovector %v",
						f.Pattern, c.Opts, subj, c.Off, rc, md.Ovector(), c.RC, c.Ovector)
				}
			}
		}
	}
	t.Logf("%d cases, %d differ from libpcre2", n, bad)
}

// TestMatchNoAlloc checks that a match with a reused match data block does not
// allocate on the hot path.
func TestMatchNoAlloc(t *testing.T) {
	var f *fixture
	for _, x := range loadFixtures(t) {
		if x.Pattern == "(a+)+b" {
			f = &x
			break
		}
	}
	if f == nil {
		t.Skip("fixture missing")
	}
	code := f.code(t)
	md := NewMatchData(code)
	mc := fixtureContext()
	subj := []byte("xxaaaaaab")
	Match(code, subj, 0, 0, md, mc) // sizes the frame vector
	allocs := testing.AllocsPerRun(100, func() { Match(code, subj, 0, 0, md, mc) })
	if allocs != 0 {
		t.Errorf("%v allocations per match, want 0", allocs)
	}
}

// FuzzMatch runs the matcher on arbitrary subjects, options and offsets with
// the bytecode of the fixture patterns: it must neither panic nor hang (the
// limits bound it) and must keep the ovector inside the subject.
func FuzzMatch(f *testing.F) {
	fixes := loadFixtures(f)
	for i := range fixes {
		for j, c := range fixes[i].Cases {
			if j%97 == 0 {
				s, _ := hex.DecodeString(c.Subject)
				f.Add(uint8(i), s, c.Off, c.Opts)
			}
		}
	}
	f.Fuzz(func(t *testing.T, which uint8, subj []byte, off uint64, opts uint32) {
		fx := &fixes[int(which)%len(fixes)]
		code := fx.code(t)
		md := NewMatchData(code)
		mc := NewMatchContext()
		mc.SetMatchLimit(2000)
		mc.SetDepthLimit(500)
		mc.SetHeapLimit(64)
		rc := Match(code, subj, off, opts, md, mc)
		if rc > 0 {
			ov := md.Ovector()
			for i := 0; i < 2*rc && i < len(ov); i += 2 {
				if ov[i] != PCRE2_UNSET && (ov[i] > uint64(len(subj)) || ov[i+1] > uint64(len(subj))) {
					t.Fatalf("ovector %v outside subject of length %d", ov[:2*rc], len(subj))
				}
			}
		}
	})
}

// TestWriteFuzzCorpus writes a corpus for FuzzMatch under testdata/fuzz
// (WRITE_FUZZ_CORPUS=1 go test -run TestWriteFuzzCorpus): one subject out of
// every 1000 fixture cases.
func TestWriteFuzzCorpus(t *testing.T) {
	if os.Getenv("WRITE_FUZZ_CORPUS") == "" {
		t.Skip()
	}
	dir := "testdata/fuzz/FuzzMatch"
	if err := os.MkdirAll(dir, 0o755); err != nil {
		t.Fatal(err)
	}
	k := 0
	for i, f := range loadFixtures(t) {
		for j, c := range f.Cases {
			if (i*7919+j)%1000 != 0 {
				continue
			}
			s, _ := hex.DecodeString(c.Subject)
			body := fmt.Sprintf("go test fuzz v1\nuint8(%d)\n[]byte(%s)\nuint64(%d)\nuint32(%d)\n", i, strconv.Quote(string(s)), c.Off, c.Opts)
			if err := os.WriteFile(fmt.Sprintf("%s/seed%03d", dir, k), []byte(body), 0o644); err != nil {
				t.Fatal(err)
			}
			k++
		}
	}
	t.Logf("%d files", k)
}
